/**
 * Recordation - Smart Selector Generator
 * Generates robust, portable, multi-strategy selectors for any DOM element.
 */

window.RecordationSelector = (function () {
  'use strict';

  // Check if string looks like autogenerated dynamic hash/ID
  function isDynamicIdentifier(str) {
    if (!str || typeof str !== 'string') return true;
    if (str.length > 40) return true;
    // Common auto-generated patterns: uuid, react :r1:, ember123, numeric, styled-components hashes
    if (/^[0-9]+$/.test(str)) return true;
    if (/^:[a-zA-Z0-9_-]+:?$/i.test(str)) return true; // React 18 useId()
    if (/^(_r_|:r|uid_)[a-zA-Z0-9_-]*/i.test(str)) return true; // React / Discord uid_
    if (/^(ember|ng-|css-|styled-|jsx-)[a-zA-Z0-9_-]+/i.test(str)) return true;
    if (/^[a-f0-9]{8}-[a-f0-9]{4}/i.test(str)) return true; // UUID
    return false;
  }

  // Get test ID if present
  function getTestId(element) {
    const testAttrs = ['data-testid', 'data-test-id', 'data-test', 'data-cy', 'data-qa', 'data-qa-id'];
    for (const attr of testAttrs) {
      const val = element.getAttribute(attr);
      if (val && val.trim()) return { attr, val: val.trim() };
    }
    return null;
  }

  // Escape special CSS characters
  function escapeCss(str) {
    if (window.CSS && CSS.escape) {
      return CSS.escape(str);
    }
    return str.replace(/([!"#$%&'()*+,.\/:;<=>?@[\\\]^`{|}~])/g, '\\$1');
  }

  // Check if a CSS selector uniquely resolves to the target element
  function isUniqueSelector(selector, target) {
    if (!selector) return false;
    try {
      const matches = document.querySelectorAll(selector);
      return matches.length === 1 && matches[0] === target;
    } catch (e) {
      return false;
    }
  }

  // Clean element inner text (first line or up to 40 chars)
  function getCleanText(element) {
    if (!element) return '';
    const text = (element.innerText || element.textContent || '').trim();
    if (!text) return '';
    // Collapse whitespace
    const clean = text.replace(/\s+/g, ' ');
    return clean.length > 50 ? clean.substring(0, 50).trim() : clean;
  }

  // Generate robust XPath
  function getXPath(element) {
    if (element.id && !isDynamicIdentifier(element.id)) {
      return `//*[@id="${element.id}"]`;
    }

    const testId = getTestId(element);
    if (testId) {
      return `//*[@${testId.attr}="${testId.val}"]`;
    }

    const parts = [];
    let current = element;

    while (current && current.nodeType === Node.ELEMENT_NODE && current !== document.documentElement) {
      if (current.id && !isDynamicIdentifier(current.id)) {
        parts.unshift(`*[@id="${current.id}"]`);
        break;
      }

      let index = 1;
      let sibling = current.previousElementSibling;
      while (sibling) {
        if (sibling.nodeName === current.nodeName) {
          index++;
        }
        sibling = sibling.previousElementSibling;
      }

      const tagName = current.nodeName.toLowerCase();
      const part = index > 1 ? `${tagName}[${index}]` : tagName;
      parts.unshift(part);

      current = current.parentElement;
    }

    return '/' + parts.join('/');
  }

  // Generate optimal CSS selector
  function getCssSelector(element) {
    if (!element || element.nodeType !== Node.ELEMENT_NODE) return '';

    const tag = element.tagName.toLowerCase();

    // 1. Test ID (highest priority)
    const testId = getTestId(element);
    if (testId) {
      const sel = `[${testId.attr}="${escapeCss(testId.val)}"]`;
      if (isUniqueSelector(sel, element)) return sel;
      const tagSel = `${tag}${sel}`;
      if (isUniqueSelector(tagSel, element)) return tagSel;
    }

    // 2. Stable ID
    if (element.id && !isDynamicIdentifier(element.id)) {
      const idSel = `#${escapeCss(element.id)}`;
      if (isUniqueSelector(idSel, element)) return idSel;
    }

    // 3. Form input names / types / placeholders
    if (element.name) {
      const nameSel = `${tag}[name="${escapeCss(element.name)}"]`;
      if (isUniqueSelector(nameSel, element)) return nameSel;
    }

    if (element.getAttribute('placeholder')) {
      const phSel = `${tag}[placeholder="${escapeCss(element.getAttribute('placeholder'))}"]`;
      if (isUniqueSelector(phSel, element)) return phSel;
    }

    if (element.getAttribute('aria-label')) {
      const ariaSel = `[aria-label="${escapeCss(element.getAttribute('aria-label'))}"]`;
      if (isUniqueSelector(ariaSel, element)) return ariaSel;
    }

    if (element.getAttribute('role')) {
      const roleSel = `${tag}[role="${escapeCss(element.getAttribute('role'))}"]`;
      if (isUniqueSelector(roleSel, element)) return roleSel;
    }

    if (element.type && ['submit', 'button', 'reset', 'checkbox', 'radio'].includes(element.type)) {
      const typeSel = `${tag}[type="${element.type}"]`;
      if (isUniqueSelector(typeSel, element)) return typeSel;
    }

    // 4. Stable classes
    if (element.className && typeof element.className === 'string') {
      const classes = element.className
        .trim()
        .split(/\s+/)
        .filter(c => c && !isDynamicIdentifier(c) && !c.startsWith('hover:') && !c.startsWith('focus:'));
      
      for (const cls of classes) {
        const clsSel = `${tag}.${escapeCss(cls)}`;
        if (isUniqueSelector(clsSel, element)) return clsSel;
      }

      if (classes.length > 1) {
        const multiCls = `${tag}.${classes.slice(0, 3).map(escapeCss).join('.')}`;
        if (isUniqueSelector(multiCls, element)) return multiCls;
      }
    }

    // 5. Hierarchical path building
    const path = [];
    let curr = element;
    while (curr && curr.nodeType === Node.ELEMENT_NODE && curr !== document.documentElement) {
      const currTag = curr.tagName.toLowerCase();
      
      if (curr.id && !isDynamicIdentifier(curr.id)) {
        path.unshift(`#${escapeCss(curr.id)}`);
        break;
      }

      const currTestId = getTestId(curr);
      if (currTestId) {
        path.unshift(`[${currTestId.attr}="${escapeCss(currTestId.val)}"]`);
        break;
      }

      // Calculate nth-of-type
      let nth = 1;
      let sib = curr.previousElementSibling;
      while (sib) {
        if (sib.tagName === curr.tagName) nth++;
        sib = sib.previousElementSibling;
      }

      // Check if tag alone is unique among siblings
      let hasSiblingSameTag = false;
      sib = curr.nextElementSibling;
      while (sib) {
        if (sib.tagName === curr.tagName) {
          hasSiblingSameTag = true;
          break;
        }
        sib = sib.nextElementSibling;
      }

      const stepSel = (nth > 1 || hasSiblingSameTag) ? `${currTag}:nth-of-type(${nth})` : currTag;
      path.unshift(stepSel);

      const candidate = path.join(' > ');
      if (isUniqueSelector(candidate, element)) {
        return candidate;
      }

      curr = curr.parentElement;
    }

    return path.join(' > ') || tag;
  }

  // Generate full inspection bundle for target element
  function inspectElement(element) {
    if (!element || element.nodeType !== Node.ELEMENT_NODE) {
      return null;
    }

    const testId = getTestId(element);
    const text = getCleanText(element);
    const rect = element.getBoundingClientRect ? element.getBoundingClientRect() : { x: 0, y: 0, width: 0, height: 0 };
    const css = getCssSelector(element);
    const xpath = getXPath(element);

    return {
      tag: element.tagName.toUpperCase(),
      text: text || null,
      selectors: {
        css: css,
        xpath: xpath,
        testId: testId ? testId.val : null,
        id: element.id && !isDynamicIdentifier(element.id) ? element.id : null,
        name: element.name || null,
        ariaLabel: element.getAttribute('aria-label') || null,
        role: element.getAttribute('role') || null,
        text: text ? text.substring(0, 40) : null
      },
      bounds: {
        x: Math.round(rect.x + window.scrollX),
        y: Math.round(rect.y + window.scrollY),
        width: Math.round(rect.width),
        height: Math.round(rect.height)
      }
    };
  }

  return {
    inspectElement,
    getCssSelector,
    getXPath,
    getCleanText,
    getTestId
  };
})();
